export const VERB_BY_ID = new Map(VERBS.map((v) => [v.id, v]))

export function verb(id: string): Verb {
  const v = VERB_BY_ID.get(id)
  if (!v) throw new Error(`unknown verb: ${id}`)
  return v
}
